<script lang="ts">
  import { onMount } from "svelte";
  import { page } from "$app/state";
  import { api, type Ticket } from "$lib/api";
  import AiInsightCard from "$lib/components/AiInsightCard.svelte";
  import PriorityChip from "$lib/components/PriorityChip.svelte";
  import StatusChip from "$lib/components/StatusChip.svelte";
  import SlaIndicator from "$lib/components/SlaIndicator.svelte";

  type Detail = Ticket & { events:{id:string;type:string;note:string|null;createdAt:string}[]; messages:{id:string;senderType:string;body:string;createdAt:string}[] };
  let ticket: Detail | null = null; let body = ""; let message = ""; let sending = false;
  const date = (value:string) => new Intl.DateTimeFormat("id-ID",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(value));
  async function load(){ ticket=await api<Detail>(`/tickets/${page.params.id}`); }
  async function sendMessage(){ if(!body.trim()) return; sending=true; try { await api(`/tickets/${page.params.id}/messages`,{method:"POST",body:JSON.stringify({body,senderType:"AGENT"})}); body=""; await load(); } catch(cause){message=cause instanceof Error?cause.message:"Gagal mengirim balasan";} finally {sending=false;} }
  async function transition(to:string){ try { await api(`/tickets/${page.params.id}/transition`,{method:"POST",body:JSON.stringify({to})}); await load(); } catch(cause){message=cause instanceof Error?cause.message:"Gagal memperbarui status";} }
  onMount(()=>{load().catch(cause=>message=cause instanceof Error?cause.message:"Gagal memuat tiket");});
  $: summary = ticket ? `${ticket.user.name} melaporkan ${ticket.category.name.toLowerCase()}: ${ticket.description.slice(0,150)}${ticket.description.length>150?"…":""}` : "";
  $: suggestion = ticket ? `Terima kasih sudah melaporkan. Tim kami sedang meninjau ${ticket.category.name.toLowerCase()} dan akan memberi pembaruan melalui tiket ini.` : "";
</script>

<svelte:head><title>{ticket ? `${ticket.code} — Ticket.Ops` : "Detail tiket — Ticket.Ops"}</title></svelte:head>
<a class="back" href="/tickets">← Kembali ke ticket queue</a>
{#if message}<p class="error">{message}</p>{/if}
{#if !ticket}<p class="loading">Menyiapkan workspace tiket…</p>{:else}
  <section class="ticket-workspace">
    <header class="heading"><div><p class="section-code">{ticket.code} · {ticket.source === "TELEGRAM" ? "Telegram intake" : "Manual request"}</p><h1>{ticket.title}</h1><p>{ticket.category.name} · {ticket.user.name}{ticket.user.department ? ` · ${ticket.user.department}` : ""}</p></div><div class="header-tags"><PriorityChip priority={ticket.priority}/><StatusChip status={ticket.status}/></div></header>
    <div class="workspace-grid">
      <main class="conversation-column">
        <article class="surface description"><div class="surface-head"><h2>Permintaan pengguna</h2><small>Dibuat {date(ticket.createdAt)}</small></div><p>{ticket.description}</p></article>
        <article class="surface thread"><div class="surface-head"><h2>Percakapan</h2><span>{ticket.messages.length} pesan</span></div><div class="messages">{#if ticket.messages.length === 0}<div class="empty-message">Belum ada pesan. Kirim respons pertama untuk memperbarui requester.</div>{:else}{#each ticket.messages as item}<div class:agent={item.senderType !== "USER"} class="message"><div><strong>{item.senderType === "USER" ? ticket.user.name : item.senderType === "AI" ? "AI assist" : "Agen helpdesk"}</strong><small>{date(item.createdAt)}</small></div><p>{item.body}</p></div>{/each}{/if}</div><form on:submit|preventDefault={sendMessage}><label for="reply">Balasan agen</label><textarea id="reply" bind:value={body} placeholder="Tulis respons yang akan diterima pengguna…" rows="4"></textarea><div><small>Balasan ini dikirim oleh agen, bukan AI.</small><button class="primary" disabled={sending} type="submit">{sending ? "Mengirim…" : "Kirim balasan"}</button></div></form></article>
        <article class="surface history"><div class="surface-head"><h2>Riwayat aktivitas</h2></div>{#each ticket.events as event}<div class="event"><i></i><div><strong>{event.type.replace("_"," ")}</strong><p>{event.note ?? "Perubahan pada tiket"}</p></div><small>{date(event.createdAt)}</small></div>{/each}</article>
      </main>
      <aside class="sidebar-column">
        <article class="surface metadata"><h2>Ringkasan tiket</h2><dl><div><dt>Requester</dt><dd>{ticket.user.name}</dd></div><div><dt>Agen penanggung jawab</dt><dd>{ticket.agent?.name ?? "Belum ditugaskan"}</dd></div><div><dt>Status</dt><dd><StatusChip status={ticket.status}/></dd></div><div><dt>SLA resolusi</dt><dd><SlaIndicator dueAt={ticket.slaResolutionDueAt} breached={ticket.slaResolutionBreached ?? false} resolved={!!ticket.resolvedAt}/></dd></div></dl><div class="actions"><span>Perbarui status</span>{#if ticket.status === "ASSIGNED"}<button class="primary" on:click={() => transition("IN_PROGRESS")}>Mulai dikerjakan</button>{:else if ticket.status === "IN_PROGRESS"}<button class="primary" on:click={() => transition("RESOLVED")}>Tandai selesai</button>{:else if ticket.status === "RESOLVED"}<button class="primary" on:click={() => transition("CLOSED")}>Tutup tiket</button>{:else}<p>{ticket.status === "CLOSED" ? "Tiket telah ditutup." : "Menunggu assignment sebelum diproses."}</p>{/if}</div></article>
        <AiInsightCard summary={summary} suggestion={suggestion} />
        <article class="surface knowledge"><p class="section-code">Knowledge context</p><h2>Referensi untuk agen</h2><p>Gunakan knowledge base untuk memeriksa SOP atau artikel terkait sebelum mengirim respons.</p><a href="/knowledge">Buka knowledge base →</a></article>
      </aside>
    </div>
  </section>
{/if}

<style>
  .back { display:inline-block; margin-bottom:1rem; color:var(--acid); font-size:.78rem; font-weight:700; text-decoration:none; }.heading { display:flex; align-items:flex-start; justify-content:space-between; gap:1rem; margin-bottom:1.5rem; }.heading h1 { margin:.35rem 0 .45rem; font-size:clamp(1.8rem,4vw,2.6rem); }.heading p:not(.section-code) { margin:0; color:var(--dim); font-size:.82rem; }.header-tags { display:flex; flex-wrap:wrap; justify-content:flex-end; gap:.45rem; }.workspace-grid { display:grid; grid-template-columns:minmax(0,1.55fr) minmax(280px,.8fr); gap:1rem; }.conversation-column,.sidebar-column { display:grid; align-content:start; gap:1rem; }.surface { padding:1.2rem; border:1px solid var(--line); border-radius:14px; background:#fff; box-shadow:0 4px 18px rgb(16 42 82 / 4%); }.surface-head { display:flex; align-items:center; justify-content:space-between; gap:.75rem; padding-bottom:.85rem; border-bottom:1px solid var(--line); }.surface h2 { margin:0; font-size:1rem; letter-spacing:-.03em; }.surface-head small,.surface-head span { color:var(--dim); font-size:.68rem; }.description > p { margin:.95rem 0 0; color:#40536e; font-size:.84rem; line-height:1.7; white-space:pre-wrap; }.messages { display:grid; gap:.75rem; margin:1rem 0; }.message { max-width:88%; padding:.75rem .85rem; border-radius:10px; background:#f1f5fa; color:#40536e; }.message.agent { justify-self:end; background:var(--blue-soft); }.message > div { display:flex; align-items:center; justify-content:space-between; gap:1rem; }.message strong { color:var(--bone); font-size:.72rem; }.message small { color:var(--dim); font-size:.64rem; }.message p { margin:.45rem 0 0; font-size:.78rem; line-height:1.5; white-space:pre-wrap; }.empty-message { padding:1rem; border-radius:9px; background:#f8fafc; color:var(--dim); font-size:.78rem; }.thread form { display:grid; gap:.55rem; padding-top:1rem; border-top:1px solid var(--line); }.thread form label { color:var(--dim); font-size:.7rem; font-weight:700; }.thread textarea { width:100%; padding:.75rem; resize:vertical; font-size:.8rem; }.thread form > div { display:flex; align-items:center; justify-content:space-between; gap:.75rem; }.thread form small { color:var(--dim); font-size:.67rem; }.thread button { padding:.65rem .85rem; font-size:.72rem; }.event { display:grid; grid-template-columns:.7rem 1fr auto; gap:.7rem; align-items:start; padding:.85rem 0; border-bottom:1px solid #eef2f7; }.event:last-child { border-bottom:0; }.event i { width:.5rem; height:.5rem; margin-top:.28rem; border-radius:50%; background:#64a5f7; }.event strong { color:var(--bone); font-size:.73rem; text-transform:capitalize; }.event p { margin:.22rem 0 0; color:var(--dim); font-size:.72rem; }.event small { color:var(--dim); font-size:.63rem; }.metadata h2 { padding-bottom:.85rem; border-bottom:1px solid var(--line); }.metadata dl { margin:0; }.metadata dl > div { display:grid; grid-template-columns:1fr auto; gap:.8rem; align-items:center; padding:.82rem 0; border-bottom:1px solid #eef2f7; }.metadata dt { color:var(--dim); font-size:.7rem; }.metadata dd { margin:0; color:var(--bone); font-size:.73rem; text-align:right; }.actions { display:grid; gap:.6rem; margin-top:1rem; }.actions > span { color:var(--dim); font-size:.7rem; font-weight:700; }.actions p { margin:0; color:var(--dim); font-size:.72rem; line-height:1.5; }.actions button { padding:.7rem; font-size:.72rem; }.knowledge p:not(.section-code) { color:var(--dim); font-size:.76rem; line-height:1.55; }.knowledge a { color:var(--acid); font-size:.74rem; font-weight:700; text-decoration:none; }.loading { color:var(--dim); }
  @media(max-width:820px){.workspace-grid{grid-template-columns:1fr}.heading{align-items:flex-start;flex-direction:column}.header-tags{justify-content:flex-start}.sidebar-column{grid-template-columns:1fr}.metadata{grid-column:1}.event{grid-template-columns:.7rem 1fr}.event small{grid-column:2}} @media(max-width:500px){.thread form>div{align-items:flex-start;flex-direction:column}.thread button{width:100%}.message{max-width:100%}}
</style>
